class Session {
 public static readonly double[] Durations={900,1800,3600,5400};
 // EndAction: 0 = keep dark red, 1 = fade out then stop, 2 = stop and put the PC to sleep (never during test runs)
 public double Seconds,FadeElapsed;public double NormalDuration=1800,Duration=1800;public bool Running,Visible,IsTest,Fading,SleepPending;public int EndAction;
 public void Start(double duration){Duration=duration;IsTest=true;Seconds=0;Play();} public Color CurrentColor {get{return ColorAt(Seconds/Duration*1800);}}
 public double FadeDuration {get{return Math.Min(60,Duration/6);}} public double Opacity {get{return Fading?Math.Max(0,1-FadeElapsed/FadeDuration):1;}}
 public void SetNormal(double duration){NormalDuration=duration;if(!IsTest){Duration=duration;if(Seconds>Duration)Seconds=Duration;}}
 public void Play(){if(Seconds>=Duration)Seconds=0;Fading=false;FadeElapsed=0;Running=true;Visible=true;}
 public void Pause(){Running=false;}
 public void Stop(){Seconds=0;Duration=NormalDuration;IsTest=false;Running=false;Visible=false;Fading=false;FadeElapsed=0;}
 public void Advance(double seconds){seconds=Math.Max(0,seconds);if(Running){double step=Math.Min(seconds,Duration-Seconds);Seconds+=step;seconds-=step;if(Seconds>=Duration){Running=false;if(EndAction==1)Fading=true;else if(EndAction==2&&!IsTest)SleepPending=true;}}if(Fading){FadeElapsed+=seconds;if(FadeElapsed>=FadeDuration)Stop();}}
 public static Color ColorAt(double seconds){double p=Math.Max(0,Math.Min(3,seconds/600));Color[] c={Color.FromArgb(255,220,0),Color.FromArgb(255,110,0),Color.FromArgb(255,0,0),Color.FromArgb(110,0,0)};int i=Math.Min(2,(int)p);double t=p-i;return Color.FromArgb((int)Math.Round(c[i].R+(c[i+1].R-c[i].R)*t),(int)Math.Round(c[i].G+(c[i+1].G-c[i].G)*t),0);}
}
static class Sun {
 public static readonly string[] Cities={"Amsterdam","Rotterdam","Den Haag","Utrecht","Eindhoven","Groningen","Zwolle","Arnhem","Maastricht","Middelburg","Leeuwarden","Brussel","Antwerpen","Gent"};
 static readonly double[,] Places={{52.37,4.90},{51.92,4.48},{52.08,4.30},{52.09,5.12},{51.44,5.48},{53.22,6.57},{52.52,6.08},{51.98,5.91},{50.85,5.69},{51.50,3.61},{53.20,5.80},{50.85,4.35},{51.22,4.40},{51.05,3.72}};
 public const int DefaultCity=3;
 static double Norm(double v,double m){v%=m;return v<0?v+m:v;}
 // NOAA sunset approximation (zenith 90.833°), accurate to a few minutes; null when the sun does not set that day
 public static DateTime? SunsetUtc(DateTime date,double lat,double lon){double rad=Math.PI/180,lngHour=lon/15,t=date.DayOfYear+(18-lngHour)/24,M=0.9856*t-3.289;double L=Norm(M+1.916*Math.Sin(M*rad)+0.020*Math.Sin(2*M*rad)+282.634,360);double RA=Norm(Math.Atan(0.91764*Math.Tan(L*rad))/rad,360);RA=(RA+Math.Floor(L/90)*90-Math.Floor(RA/90)*90)/15;double sinDec=0.39782*Math.Sin(L*rad),cosDec=Math.Cos(Math.Asin(sinDec));double cosH=(Math.Cos(90.833*rad)-sinDec*Math.Sin(lat*rad))/(cosDec*Math.Cos(lat*rad));if(cosH<-1||cosH>1)return null;double H=Math.Acos(cosH)/rad/15,UT=Norm(H+RA-0.06571*t-6.622-lngHour,24);return new DateTime(date.Year,date.Month,date.Day,0,0,0,DateTimeKind.Utc).AddHours(UT);}
 // Sunset as minutes after local midnight of that day
 public static int? SunsetMinutes(DateTime day,int city){var u=SunsetUtc(day,Places[city,0],Places[city,1]);if(u==null)return null;return (int)Math.Round((u.Value.ToLocalTime()-day.Date).TotalMinutes);}
}
