 // Starts a planned session once per day, using the first scheduled profile for that weekday; opened late, it catches up so the color matches the clock
 bool CheckSchedule(DateTime now){if(lastRun==now.Date)return false;for(int i=0;i<profiles.Length;i++){var p=profiles[i];if(!p.Scheduled||!p.Days[(int)now.DayOfWeek])continue;double late=(now-now.Date.AddMinutes(StartMinutesFor(p,now.Date))).TotalSeconds;if(late<0||late>=p.Duration)continue;lastRun=now.Date;if(session.Visible){SaveSettings(true);return false;}if(i!=current)SelectProfile(i);watch.Reset();session.Stop();session.Play();session.Advance(late);watch.Restart();SaveSettings(true);Apply();return true;}return false;}
