 planningLabel.Text=T("Planning","Schedule");scheduled.Text=T("Automatisch starten om","Start automatically at");follow.Text=T("Elke dag meeschuiven met de zonsondergang","Shift with the sunset every day");save.Text=T("Opslaan","Save");
